```python
# code related to speed limits and performance tuning
class Bike:
    def __init__(self, top_speed, limit):
        self.top_speed = top_speed
        self.limit = limit
    
    def accelerate(self, speed_increase):
        if (self.top_speed + speed_increase) > self.limit:
            self.top_speed = self.limit
        else: 
            self.top_speed += speed_increase
        return self.top_speed

def tune_bike(bike, tuning_level):
    if tuning_level == 'basic':
        bike.top_speed += 20
    elif tuning_level == 'advanced':
        bike.top_speed += 50
    else:
        print("Invalid tuning level")
    return bike.top_speed

moto = Bike(top_speed=120, limit=160)
print(moto.accelerate(30)) # prints 150
print(tune_bike(moto, 'basic')) # prints 140
